/**
 * CPython's `int(str)` coercion.
 *
 * Accepts surrounding Unicode whitespace, an optional sign, Unicode decimal digits
 * (not just ASCII) and PEP 515 underscore separators between digits. Values are
 * arbitrary precision, so the result is a BigInt.
 */

/** Code points for which Python's Py_UNICODE_ISSPACE is true. */
const WHITESPACE = new Set(
  [
    0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20, 0x85, 0xa0, 0x1680,
    0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007, 0x2008, 0x2009,
    0x200a, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
  ],
);

/** Raised for input `int()` would reject; the caller turns it into an argparse error. */
export class PyValueError extends Error {}

const DECIMAL_DIGIT = /\p{Nd}/u;
const INT_LITERAL = /^([+-]?)(\p{Nd}+(?:_\p{Nd}+)*)$/u;

function isSpace(ch) {
  return WHITESPACE.has(ch.codePointAt(0));
}

function strip(text) {
  const chars = Array.from(text);
  let start = 0;
  let end = chars.length;
  while (start < end && isSpace(chars[start])) start += 1;
  while (end > start && isSpace(chars[end - 1])) end -= 1;
  return chars.slice(start, end).join('');
}

/**
 * Numeric value of a Unicode decimal digit. Unicode guarantees decimal digits come
 * in contiguous runs of ten starting at the script's zero, so walking backwards to
 * the first non-digit code point recovers the offset within the run.
 */
function decimalValue(ch) {
  const cp = ch.codePointAt(0);
  if (cp >= 0x30 && cp <= 0x39) return cp - 0x30;
  for (let back = 1; back <= 10 && cp - back >= 0; back += 1) {
    if (!DECIMAL_DIGIT.test(String.fromCodePoint(cp - back))) return back - 1;
  }
  return 0;
}

export function pyInt(text) {
  const match = INT_LITERAL.exec(strip(text));
  if (match === null) throw new PyValueError(`invalid literal for int() with base 10: ${text}`);

  const [, sign, body] = match;
  let ascii = '';
  for (const ch of body) {
    if (ch !== '_') ascii += String(decimalValue(ch));
  }
  return BigInt(sign === '-' ? `-${ascii}` : ascii);
}

/** `int.__name__`, used verbatim in argparse's "invalid int value" message. */
pyInt.pyName = 'int';

