/**
 * An undirected graph with the same storage model as `networkx.Graph`:
 * an insertion-ordered node table, and per node an insertion-ordered adjacency
 * table mapping neighbour -> shared edge-attribute object.
 *
 * The ordering is not incidental — BFS/DFS/Dijkstra all iterate adjacency in
 * insertion order, so it decides the exact output. Re-assigning an existing key
 * keeps its original position in both Python dicts and JS Maps, which is why a
 * duplicate edge updates the weight without moving the neighbour.
 *
 * Node ids are BigInt (Python ints); Map compares BigInt keys by value.
 */

export class Graph {
  constructor() {
    this._adj = new Map();
  }

  addNode(node) {
    if (!this._adj.has(node)) this._adj.set(node, new Map());
  }

  /** `G.add_edge(u, v, **attr)`: both directions share one attribute object. */
  addEdge(u, v, attr) {
    this.addNode(u);
    this.addNode(v);
    const data = this._adj.get(u).get(v) ?? {};
    Object.assign(data, attr);
    this._adj.get(u).set(v, data);
    this._adj.get(v).set(u, data);
  }

  /** `G.add_weighted_edges_from(ebunch)` for `[u, v, weight]` triples. */
  addWeightedEdgesFrom(ebunch, weightKey = 'weight') {
    for (const [u, v, weight] of ebunch) {
      this.addEdge(u, v, { [weightKey]: weight });
    }
  }

  numberOfNodes() {
    return this._adj.size;
  }

  nodes() {
    return this._adj.keys();
  }

  hasNode(node) {
    return this._adj.has(node);
  }

  /** Adjacency table of `node` (`G[node]`). */
  adj(node) {
    return this._adj.get(node);
  }

  neighbors(node) {
    return this._adj.get(node).keys();
  }

  hasEdge(u, v) {
    const nbrs = this._adj.get(u);
    return nbrs !== undefined && nbrs.has(v);
  }

  /** `G[u][v]`, the shared attribute object. */
  getEdgeData(u, v) {
    return this._adj.get(u)?.get(v);
  }

  /** Degree as networkx counts it: a self-loop contributes 2. */
  degree(node) {
    const nbrs = this._adj.get(node);
    return nbrs.size + (nbrs.has(node) ? 1 : 0);
  }

  /** `G.degree()`: `[node, degree]` pairs in node insertion order. */
  *degrees() {
    for (const node of this._adj.keys()) yield [node, this.degree(node)];
  }

  /**
   * `G.edges(data=True)`: every edge once, in networkx's order — outer loop over
   * nodes, inner loop over adjacency, skipping neighbours already emitted. A
   * self-loop is yielded once.
   */
  *edges() {
    const seen = new Set();
    for (const [node, nbrs] of this._adj) {
      for (const [nbr, data] of nbrs) {
        if (!seen.has(nbr)) yield [node, nbr, data];
      }
      seen.add(node);
    }
  }

  numberOfEdges() {
    let count = 0;
    for (const _edge of this.edges()) count += 1;
    return count;
  }
}

