    for (const parent of level) {
      for (const child of G.neighbors(parent)) {
        if (visited.has(child)) continue;
        yield [parent, child];
        visited.add(child);
        nextLevel.push(child);
      }
      if (visited.size === total) return;
    }
    level = nextLevel;
  }
}

/**
 * `nx.dfs_edges(G, source)`: an explicit stack of *stateful* neighbour iterators.
 * Resuming a parent continues where its iterator left off rather than rescanning
 * from the start, which is observable whenever a parent has several unvisited
 * neighbours.
 */
export function* dfsEdges(G, source) {
  const depthLimit = G.numberOfNodes();
  const visited = new Set([source]);
  const stack = [{ node: source, children: G.neighbors(source) }];
  let depth = 1;

  while (stack.length > 0) {
    const frame = stack[stack.length - 1];
    let descended = false;

    for (;;) {
      const step = frame.children.next();
      if (step.done) break;
      const child = step.value;
      if (visited.has(child)) continue;
      yield [frame.node, child];
      visited.add(child);
      if (depth < depthLimit) {
        stack.push({ node: child, children: G.neighbors(child) });
        depth += 1;
        descended = true;
        break;
      }
    }

    if (!descended) {
      stack.pop();
      depth -= 1;
    }
  }
}

