const NEGATIVE_NUMBER = /^-\p{Nd}+$|^-\p{Nd}*\.\p{Nd}+$/u;

const INDENT = '  ';
const MAX_HELP_POSITION = 24;

export class ArgumentParser {
  constructor({ prog }) {
    this.prog = prog;
    this._actions = [];
    this._optionStringActions = new Map();
    this.addArgument(['-h', '--help'], { action: 'help', help: 'show this help message and exit' });
  }

  addArgument(optionStrings, { action = 'store', type = null, required = false, metavar = null, help = null } = {}) {
    const dest = optionStrings[optionStrings.length - 1].replace(/^-+/, '').replace(/-/g, '_');
    const entry = {
      optionStrings,
      dest,
      action,
      type,
      required,
      // argparse defaults an optional's metavar to the upper-cased dest.
      metavar: metavar ?? dest.toUpperCase(),
      help,
      nargs: action === 'help' ? 0 : 1,
