#!/usr/bin/env node
/**
 * Node.js port of dataset/networkx/test10.py.
 *
 * Builds a weighted undirected graph from five integer arguments and prints the
 * same nine lines the Python/networkx original does, byte for byte — including
 * Python's `repr` formatting, its insertion-order-driven traversal output, and
 * networkx's own node-connectivity search.
 *
 * Usage: node test10.mjs --a 1 --b 2 --c 3 --d 4 --e 5
 */

import { ParserExit } from './lib/cli/argparse.mjs';
import { parseArgs } from './lib/cli/args.mjs';
import { pyPrint, tuple } from './lib/python/repr.mjs';
import {
  Graph,
  bfsEdges,
  dfsEdges,
  dijkstraPath,
  dijkstraPathLength,
  minimumSpanningTree,
  nodeConnectivity,
} from './lib/graph/index.mjs';

/** Python ints render from BigInt; counts computed as Numbers cross over here. */
const asPyInt = (count) => BigInt(count);

const edgeTuples = (edges) => [...edges].map(([u, v]) => tuple(u, v));

export function main(argv) {
  const args = parseArgs(argv);

  const G = new Graph();
  G.addWeightedEdgesFrom([
    [args.a, args.b, 1.0],
    [args.b, args.c, 2.0],
    [args.c, args.d, 3.0],
    [args.d, args.e, 4.0],
    [args.a, args.e, 5.0],
  ]);

  pyPrint(asPyInt(G.numberOfEdges())); // 获取边数量
  pyPrint(G.getEdgeData(args.a, args.b).weight); // 获取边权重
  const mst = minimumSpanningTree(G); // 最小生成树
  pyPrint(asPyInt(mst.numberOfEdges())); // MST边数量
  pyPrint(mst.hasEdge(args.a, args.b)); // 检查MST中的边
  // Zero length keeps Python's int 0; any real path length is a float.
  const length = dijkstraPathLength(G, args.a, args.e); // Dijkstra最短路径长度
  pyPrint(length.isFloat ? length.value : asPyInt(length.value));
  pyPrint(dijkstraPath(G, args.a, args.e)); // Dijkstra最短路径
  pyPrint(edgeTuples(bfsEdges(G, args.a))); // BFS边
  pyPrint(edgeTuples(dfsEdges(G, args.a))); // DFS边
  pyPrint(asPyInt(nodeConnectivity(G))); // 节点连通性
}

try {
  main(process.argv.slice(2));
} catch (err) {
  // argparse exits through ParserExit so pending output is flushed first.
  if (err instanceof ParserExit) process.exitCode = err.status;
  else throw err;
}

