/**
 * The slice of argparse's `HelpFormatter` that affects output bytes: terminal-width
 * discovery, usage wrapping, and the two-column options list.
 *
 * argparse sizes everything from `shutil.get_terminal_size().columns - 2`, so a
 * narrow terminal (or a `COLUMNS` setting) rewraps both `--help` and the usage line
 * that precedes every error message.
 */

import { pyInt } from '../python/int.mjs';

const FALLBACK_COLUMNS = 80;

/**
 * `shutil.get_terminal_size().columns`: `$COLUMNS` when it parses as a positive
 * int, otherwise the tty width, otherwise 80 (which is also what Python falls back
 * to when stdout is a pipe or a file).
 */
export function terminalColumns() {
  const configured = process.env.COLUMNS;
  if (configured !== undefined) {
    try {
      const columns = Number(pyInt(configured));
      if (columns > 0) return columns;
    } catch {
      // int() would raise ValueError; Python then falls through to the tty query.
    }
  }
  return process.stdout.columns ?? FALLBACK_COLUMNS;
}

/**
 * `textwrap.wrap` for pre-collapsed single-spaced text: greedy fill, dropping the
 * separating spaces and hard-splitting a word that cannot fit on a line of its own.
 * Hyphen splitting is not modelled — no help string in this parser contains one.
 */
export function wrapText(text, width) {
  const chunks = text.split(' ').filter((chunk) => chunk !== '');
  const lines = [];
  let current = [];
  let length = 0;

  const flush = () => {
    if (current.length > 0) {
      lines.push(current.join(' '));
      current = [];
      length = 0;
    }
  };

  for (let chunk of chunks) {
    for (;;) {
      const separator = current.length === 0 ? 0 : 1;
      if (length + separator + chunk.length <= width) {
        current.push(chunk);
        length += separator + chunk.length;
        break;
      }
      if (current.length > 0) {
        flush();
        continue;
      }
      lines.push(chunk.slice(0, width));
      chunk = chunk.slice(width);
      if (chunk === '') break;
    }
  }
  flush();
  return lines;
}

const USAGE_PREFIX = 'usage: ';

export class HelpFormatter {
  constructor(prog, { width = terminalColumns() - 2, indentIncrement = 2, maxHelpPosition = 24 } = {}) {
    this.prog = prog;
    this._width = width;
    this._indentIncrement = indentIncrement;
    // argparse shrinks the help column on narrow terminals before anything else.
    this._maxHelpPosition = Math.min(maxHelpPosition, Math.max(width - 20, indentIncrement * 2));
  }

  /** How an action appears in the usage line: `[-h]`, `--a A`. */
  _usagePart(action) {
    const invocation =
      action.nargs === 0 ? action.optionStrings[0] : `${action.optionStrings[0]} ${action.metavar}`;
    return action.required ? invocation : `[${invocation}]`;
  }

  /** How an action appears in the options list: `-h, --help`, `--a A`. */
  _invocation(action) {
    if (action.nargs === 0) return action.optionStrings.join(', ');
    return action.optionStrings.map((option) => `${option} ${action.metavar}`).join(', ');
  }

  /** `parser.format_usage()`: one line, or the wrapped form when it does not fit. */
  formatUsage(actions) {
    const parts = actions.map((action) => this._usagePart(action));
    const oneLine = [this.prog, parts.join(' ')].filter((piece) => piece !== '').join(' ');
    const textWidth = this._width;

    if (USAGE_PREFIX.length + oneLine.length <= textWidth) {
      return `${USAGE_PREFIX}${oneLine}\n`;
    }

    // argparse packs the parts greedily; `linePrefix` marks the line that already
    // carries "usage: " so its indent is stripped back off at the end.
    const getLines = (chunks, indent, linePrefix) => {
      const lines = [];
      let line = [];
      let lineLength = (linePrefix === undefined ? indent.length : linePrefix.length) - 1;
      for (const part of chunks) {
        if (lineLength + 1 + part.length > textWidth && line.length > 0) {
          lines.push(indent + line.join(' '));
          line = [];
          lineLength = indent.length - 1;
        }
        line.push(part);
        lineLength += 1 + part.length;
      }
      if (line.length > 0) lines.push(indent + line.join(' '));
      if (linePrefix !== undefined && lines.length > 0) lines[0] = lines[0].slice(indent.length);
      return lines;
    };

    let lines;
    if (USAGE_PREFIX.length + this.prog.length <= 0.75 * textWidth) {
      // Short prog: the first group of parts shares its line.
      const indent = ' '.repeat(USAGE_PREFIX.length + this.prog.length + 1);
      lines = parts.length > 0 ? getLines([this.prog, ...parts], indent, USAGE_PREFIX) : [this.prog];
    } else {
      // Long prog: it gets a line to itself and the parts hang under "usage: ".
      lines = [this.prog, ...getLines(parts, ' '.repeat(USAGE_PREFIX.length))];
    }
    return `${USAGE_PREFIX}${lines.join('\n')}\n`;
  }

  /** `parser.format_help()`: the usage block plus the indented options section. */
  formatHelp(actions, heading = 'options') {
    const invocations = actions.map((action) => this._invocation(action));
    const actionMaxLength = Math.max(
      0,
      ...invocations.map((text) => text.length + this._indentIncrement),
    );
    const helpPosition = Math.min(actionMaxLength + 2, this._maxHelpPosition);
    const helpWidth = Math.max(this._width - helpPosition, 11);
    const actionWidth = helpPosition - this._indentIncrement - 2;
    const indent = ' '.repeat(this._indentIncrement);

    let body = '';
    actions.forEach((action, index) => {
      const header = invocations[index];
      if (action.help === null || action.help === '') {
        body += `${indent}${header}\n`;
        return;
      }
      let firstLineIndent;
      if (header.length <= actionWidth) {
        body += `${indent}${header.padEnd(actionWidth)}  `;
        firstLineIndent = 0;
      } else {
        body += `${indent}${header}\n`;
        firstLineIndent = helpPosition;
      }
      const lines = wrapText(action.help.replace(/\s+/g, ' ').trim(), helpWidth);
      body += `${' '.repeat(firstLineIndent)}${lines[0]}\n`;
      for (const line of lines.slice(1)) body += `${' '.repeat(helpPosition)}${line}\n`;
    });

    const text = `${this.formatUsage(actions)}\n${heading}:\n${body}`;
    // argparse collapses runs of blank lines and normalises to one trailing newline.
    return `${text.replace(/\n{3,}/g, '\n\n').replace(/^\n+|\n+$/g, '')}\n`;
  }
}

